tasks = {
    '登录接口': [],
    '用户表': [],
    '会话校验': ['登录接口', '用户表'],
    '权限中间件': ['会话校验'],
    '订单接口': ['权限中间件'],
    '前端登录页': ['登录接口'],
}


def impacted(tasks, changed):
    affected = set(changed)
    changed_work = True
    while changed_work:
        changed_work = False
        for name, deps in tasks.items():
            if name in affected:
                continue
            if any(dep in affected for dep in deps):
                affected.add(name)
                changed_work = True
    return affected


print(sorted(impacted(tasks, ['用户表'])))
print(sorted(impacted(tasks, ['前端登录页'])))
